props.code:
function run(ctx) {
  ctx.openDecision("Which payment provider?", {criteria: ["fees", "markets"], threshold: 0.7, maxRounds: 3});
  return "decision point opened";
}

function run(ctx) {
  const d = ctx.decisionPoints().find(p => p.status === "open" || p.status === "escalated");
  if (!d) return "nothing to decide";
  const answered = d.questions.filter(q => q.status === "answered");
  if (answered.length === 0) {
    ctx.undecidable(d.id, "the fees decide between the options and are unknown", ["What are the fees of each payment provider?"]);
    return "undecidable: fees unknown";
  }
  const pick = ctx.options().find(o => o.name === "stripe") || ctx.options()[0];
  ctx.decide(d.id, pick.name, 0.9, "the lowest fees in our markets");
  return "decided " + pick.name;
}

function run(ctx) {
  ctx.addArtifact("fees", {stripe: "1.4%", adyen: "1.6%"});
  return "fees analysed";
}

