props.code:
function run(ctx) {
  const reqs = ctx.nodes("alm@Requirement");
  for (const r of reqs) ctx.impactNode(r.key, "in the scope of the campaign");
  ctx.log(reqs.length + " requirement(s) retained");
  return reqs.length + " requirement(s)";
}

for (const n of ctx.changeImpacts()) {
  if (!n.pre || n.type !== "alm@Requirement" || n.intent !== "modified") continue;
  const title = "Verify " + n.key + ": " + n.pre.props.title;
  const t = ctx.impactNodeCreate("alm@TestCase", "TC-" + n.key, "verifies " + n.key);
  ctx.writeNode(t, {
    props: { title: title },
    links: [{ type: "alm@verifies", to: n.key }],
  });
}

const tests = ctx.changeImpacts().filter(n => n.intent === "created");
const r = ctx.complete({
  model: "fast",
  prompt: "Summarize in three lines a campaign of " + tests.length + " test cases: " +
          tests.map(t => t.post ? t.post.props.title : t.key).join("; "),
});
ctx.addArtifact("summary", { markdown: r.text, tests: tests.length });

for (const n of ctx.changeImpacts()) {
  if (n.intent === "created" && n.review === "proposed") ctx.impactNodeReview(n.key, true, "automatic review");
}

const design = ctx.runAgent("test-designer", "design the test cases");
if (design.status !== "completed") throw new Error("design: " + design.status);
const review = ctx.runAgent("reviewer", "review the test cases");
if (review.status !== "completed") throw new Error("review: " + review.status);
ctx.log("campaign designed and reviewed");

ctx.wakeOn("progress");
const r = ctx.runAgent("pinger", "notify the parent step by step");
ctx.setVar("childStatus", r.status);
ctx.log("child status: " + r.status);

