props.code:
function run(ctx) {
  const scopes = ctx.items("artifact").filter(a => a.target === "poc_scope");
  const scope = scopes[scopes.length - 1].data;
  let n = 0;
  for (const h of (scope.hypotheses || [])) {
    n++;
    ctx.addItem("hypothesis", { key: "HYP-" + n, statement: String(h.statement), source: String(h.source || "framing") });
  }
  if (n === 0) throw new Error("the POC was opened with nothing to check");
  return n + " hypothesis(es) to check";
}

props.prompt:
You prepare a proof of concept: the smallest code that shows whether a hypothesis holds. It is a throw-away
build, without the quality rules of a delivery (no coverage, no review), but its check must be honest: a command
whose exit code says whether what is observed is what is expected.
Proof of concept: "{{ .Change.Title }}" — {{ .Change.Intent }}
Hypothesis {{ .Subject.data.key }}: {{ .Subject.data.statement }}
The brief gives the scope (sources, timebox, notes) in its artifacts.
Answer {"items":[{"type":"artifact","target":"probe","data":{"hypothesis":"{{ .Subject.data.key }}",
  "build":"<what to build, in a few lines>","observe":"<what to measure or observe>",
  "refutes":"<the result that shows it works as expected>","dir":"<the directory of the workspace it is built in: a source, or probe-{{ .Subject.data.key }}>",
  "check":"<the shell command, run in dir, whose exit code 0 shows it works>"}}]}

props.code:
function run(ctx) {
  const scopes = ctx.items("artifact").filter(a => a.target === "poc_scope");
  const repos = (scopes[scopes.length - 1].data.repositories || []).filter(r => r);
  const ws = ctx.callTool("workspace/open", { sources: repos.map(r => ({ repo: r })) });
  ctx.addArtifact("workspace", { directory: ws.directory, sources: ws.sources });
  return repos.length + " source(s) in the workspace";
}

props.prompt:
You build a PROOF OF CONCEPT: the smallest code that shows whether a hypothesis holds. Relaxed rules: no
coverage, no lint, no review, shortcuts welcome; but do not fake the result, the check decides.
Proof of concept: "{{ .Change.Title }}" — {{ .Change.Intent }}
Hypothesis {{ .Subject.data.key }}: {{ .Subject.data.statement }}
{{ range .Artifacts }}{{ if and (eq .Target "probe") (eq (index .Data "hypothesis") $.Subject.data.key) }}Probe: build {{ index .Data "build" }}; observe {{ index .Data "observe" }}; it works when {{ index .Data "refutes" }}.
Build it in the directory {{ index .Data "dir" }} of the workspace; its check is `{{ index .Data "check" }}`, run there.
{{ end }}{{ if and (eq .Target "probe_report") (eq (index .Data "hypothesis") $.Subject.data.key) }}A run of the check {{ if index .Data "ok" }}succeeded{{ else }}FAILED{{ end }} (after change {{ index .Data "revision" }}):
{{ index .Data "output" }}
{{ end }}{{ end }}
Work with the workspace tools (create the directory if it does not exist, git init it if it is no source), run
the check yourself, then commit your work there (git add -A && git commit -m "<what>"). Finish with:
{"items":[{"type":"artifact","target":"probe_change","data":{"hypothesis":"{{ .Subject.data.key }}","summary":"<what you built>","files":["<paths>"]}}]}

props.code:
function run(ctx) {
  const h = ctx.var("item").data.key;
  const probes = ctx.items("artifact").filter(a => a.target === "probe" && a.data.hypothesis === h);
  const probe = probes[probes.length - 1].data;
  const revision = ctx.items("artifact").filter(a => a.target === "probe_change" && a.data.hypothesis === h).length;
  const r = ctx.callTool("workspace/bash", { command: probe.check, cwd: probe.dir || ".", timeout: 600 });
  const out = String(r.stdout || "") + String(r.stderr || "");
  const ok = r.exitCode === 0 && !r.timedOut;
  ctx.addArtifact("probe_report", { hypothesis: h, ok: ok, exitCode: r.exitCode, command: probe.check, dir: probe.dir || ".",
    revision: revision, output: out.length > 4000 ? "..." + out.slice(out.length - 4000) : out });
  return h + (ok ? ": works as expected" : ": does not show it works");
}

props.prompt:
A proof of concept checked a hypothesis; judge it from the evidence only.
Hypothesis {{ .Subject.data.key }}: {{ .Subject.data.statement }}
{{ range .Artifacts }}{{ if and (eq .Target "probe") (eq (index .Data "hypothesis") $.Subject.data.key) }}Probe: {{ index .Data "build" }}; it works when {{ index .Data "refutes" }}.
{{ end }}{{ if and (eq .Target "probe_report") (eq (index .Data "hypothesis") $.Subject.data.key) }}Check `{{ index .Data "command" }}` after change {{ index .Data "revision" }}: {{ if index .Data "ok" }}succeeded{{ else }}FAILED{{ end }}
{{ index .Data "output" }}
{{ end }}{{ end }}
The verdict is "refuted" when the latest check shows it works as expected (a risk that does not hold, a need the
prototype answers), "confirmed" otherwise (the risk holds, or the probe could not show it works). The score is
your confidence, 0 to 5.
Answer {"items":[{"type":"assessment","data":{"key":"item:{{ .Subject.data.key }}","verdict":"<refuted|confirmed>","score":<0-5>,
  "findings":[{"text":"<what the probe showed>","severity":"info"}],"suggestion":"<what the change should do with it>"}}]}

props.code:
function run(ctx) {
  const st = ctx.callTool("workspace/status", {});
  const kept = [];
  for (const s of (st.sources || [])) {
    if (!s.remote) continue; // a scratch directory of a mock-up has nowhere to go
    const pushed = ctx.callTool("workspace/push", { path: s.path });
    kept.push({ path: s.path, branch: pushed.branch, commit: pushed.head, remote: pushed.remote });
  }
  ctx.addArtifact("probes_kept", { branches: kept });
  return kept.length + " branch(es) kept";
}

