function run(ctx) {
  const required = {
    Component: ["implements"], Interface: ["exposed_by"], Flow: ["source", "target", "carries"],
    BuildArtifact: ["built_from"], Data: ["owned_by"],
  };
  const issues = [];
  for (const n of ctx.changeImpacts()) {
    const kind = n.type.split("@").pop();
    if (n.intent !== "created" || !required[kind]) continue;
    if (n.planned) { issues.push(n.type + " " + n.key + " : planned, not designed yet (write or withdraw it)"); continue; }
    for (const t of required[kind]) {
      if (!n.post || !n.links.some(l => l.type === "alm@" + t)) issues.push(n.type + " " + n.key + " : missing link \"" + t + "\"");
    }
  }
  for (const i of issues) ctx.warn(i);
  ctx.addArtifact("design_check", { ok: issues.length === 0, issues: issues });
  return issues.length + " issue(s)";
}

