function run(ctx) {
  const nodes = ctx.changeImpacts();
  // needs in scope: impacted, or satisfied by the impacted requirements
  const needs = new Set();
  for (const n of nodes) {
    if (n.intent !== "modified" || !n.pre) continue;
    if (n.type === "alm@Need") needs.add(n.key);
    if (n.type.endsWith("Requirement")) {
      for (const l of ctx.links(n.key, "out", "alm@satisfies")) needs.add(l.to.key);
    }
  }
  let k = 0;
  for (const r of nodes) {
    if (r.intent !== "created" || !r.post || !r.type.endsWith("Requirement")) continue;
    if (r.links.some(l => l.type === "alm@satisfies" || l.type === "alm@refines")) continue;
    if (needs.size === 0) { ctx.warn(r.key + " : no need in scope"); continue; }
    ctx.writeNode(r.key, { links: [...needs].map(need => ({ type: "alm@satisfies", to: need })) });
    k += needs.size;
  }
  return k + " traceability link(s) written";
}

function run(ctx) {
  const nodes = ctx.changeImpacts();
  const verified = new Set();
  for (const t of nodes) {
    if (t.intent === "created" && t.post) for (const l of t.links) if (l.type === "alm@verifies") verified.add(l.to.key);
  }
  let n = 0;
  for (const r of nodes) {
    if (!r.post || !r.type.endsWith("Requirement") || verified.has(r.key)) continue;
    const level = r.type === "alm@SecurityRequirement" ? "security"
      : r.type === "alm@NonFunctionalRequirement" ? "performance" : "acceptance";
    const title = (r.post.props && r.post.props.title) || r.key;
    const t = ctx.impactNodeCreate("alm@TestCase", "TST-" + r.key, "verifies " + r.key);
    ctx.writeNode(t, { props: { title: "Verify: " + title, level: level }, links: [{ type: "alm@verifies", to: r.key }] });
    n++;
  }
  return n + " test case(s) created";
}

function run(ctx) {
  const nodes = ctx.changeImpacts();
  const realized = new Set();
  for (const f of nodes) if (f.post) for (const l of f.links) if (l.type === "alm@realizes") realized.add(l.to.key);
  // the impacted functions, and the ones the analysis planned (written here at their first allocation)
  const functions = nodes.filter(f => f.type === "alm@Function" && (f.intent === "modified" || f.planned)).map(f => f.key).sort();
  const planned = new Set(nodes.filter(f => f.planned && f.type === "alm@Function").map(f => f.key));
  let n = 0;
  for (const r of nodes) {
    if (r.intent !== "created" || !r.post || !r.type.endsWith("Requirement") || realized.has(r.key)) continue;
    let fn = functions[0];
    if (!fn) {
      fn = ctx.impactNodeCreate("alm@Function", "FCT-" + r.key, "realizes " + r.key);
      ctx.writeNode(fn, { props: { title: "Function: " + ((r.post.props && r.post.props.title) || r.key) }, links: [{ type: "alm@realizes", to: r.key }] });
    } else if (planned.delete(fn)) {
      ctx.writeNode(fn, { props: { title: "Function: " + ((r.post.props && r.post.props.title) || r.key) }, links: [{ type: "alm@realizes", to: r.key }] });
    } else {
      ctx.writeNode(fn, { links: [{ type: "alm@realizes", to: r.key }] });
    }
    n++;
  }
  return n + " allocation(s)";
}

