actions.code:
const COMMANDS = { java: "mvn -B -q verify", go: "go build ./... && go test ./...", c: "make && make test",
                   shell: "shellcheck $(git ls-files '*.sh')", node: "npm ci && npm test", python: "python -m pytest -q" };
function run(ctx) {
  const c = ctx.var("item");
  const props = c.props || {};
  const command = props.buildCommand || COMMANDS[props.technology] || "git diff --quiet HEAD";
  const revision = ctx.items("artifact").filter(a => a.target === "code_change" && a.data.component === c.key).length;
  const r = ctx.callTool("workspace/bash", { command: command, cwd: c.key, timeout: 600 });
  const out = String(r.stdout || "") + String(r.stderr || "");
  const ok = r.exitCode === 0 && !r.timedOut;
  ctx.addArtifact("build_report", { component: c.key, ok: ok, exitCode: r.exitCode, command: command, revision: revision,
    output: out.length > 4000 ? "..." + out.slice(out.length - 4000) : out });
  return c.key + (ok ? " builds" : " does not build");
}

function bump(v) {
  const p = String(v || "0.0.0").split(".");
  while (p.length < 3) p.push("0");
  p[2] = String((parseInt(p[2], 10) || 0) + 1);
  return p.join(".");
}
function run(ctx) {
  const c = ctx.var("item");
  const props = c.props || {};
  const reports = ctx.items("artifact").filter(a => a.target === "build_report" && a.data.component === c.key && a.data.ok);
  const report = reports[reports.length - 1].data;
  const pushed = ctx.callTool("workspace/push", { path: c.key });
  const v = bump(props.version);
  const key = "ART-" + c.key + "-" + v;
  const art = ctx.impactNodeCreate("alm@BuildArtifact", key, "build artifact of " + c.key + ", branch " + pushed.branch);
  ctx.writeNode(art, { props: { name: String(props.title || c.key), format: "source", version: v, technology: props.technology || "",
    coordinates: pushed.remote + "#" + pushed.head, toolchain: report.command,
    checks: { command: report.command, exitCode: report.exitCode, commit: pushed.head } }, links: [{ type: "alm@built_from", to: c.key }] });
  if (c.intent === "modified") {
    // the applications composed of the component deploy the new artifact
    const declared = new Set(ctx.changeImpacts().map(n => n.key));
    for (const l of ctx.links(c.key, "in", "alm@composed_of")) {
      const app = l.from.key;
      if (!declared.has(app)) { ctx.impactNode(app, "deploys the new artifact " + key); declared.add(app); }
      ctx.writeNode(app, { links: [{ type: "alm@deploys", to: key }] });
    }
  }
  ctx.addArtifact("build", { component: c.key, technology: props.technology || "", version: v, artifact: key,
    toolchain: report.command, checks: [report.command], branch: pushed.branch, commit: pushed.head });
  return c.key + " published at " + pushed.head;
}

function bumpMinor(v) {
  const p = String(v || "0.0").split(".");
  while (p.length < 2) p.push("0");
  p[1] = String((parseInt(p[1], 10) || 0) + 1);
  return p.slice(0, 2).join(".");
}
function run(ctx) {
  const nodes = ctx.changeImpacts();
  const artifacts = new Set(nodes.filter(n => n.intent === "created" && n.type === "alm@BuildArtifact").map(n => n.key));
  // applications receiving a new artifact (deploys links written by the build)
  const byApp = new Map();
  for (const n of nodes) {
    if (!n.post) continue;
    for (const l of n.links) {
      if (l.type !== "alm@deploys" || !artifacts.has(l.to.key)) continue;
      if (!byApp.has(n.key)) byApp.set(n.key, []);
      byApp.get(n.key).push(l.to.key);
    }
  }
  const releases = [];
  for (const [app, arts] of byApp) {
    const node = ctx.node(app);
    const v = bumpMinor(node.props.version);
    const key = "REL-" + app + "-" + v;
    const r = ctx.impactNodeCreate("alm@Release", key, "release " + v + " of " + app);
    ctx.writeNode(r, {
      props: { title: (node.props.title || app) + " " + v, version: v, status: "candidate" },
      links: [{ type: "alm@releases", to: app }].concat(arts.map(a => ({ type: "alm@contains", to: a }))),
    });
    releases.push(key);
  }
  // environment chain: ascending order (order property)
  const pipeline = ctx.nodes("alm@Environment")
    .map(e => ({ key: e.key, name: e.props.name || e.key, stage: e.props.stage || "", order: Number(e.props.order || 0) }))
    .sort((a, b) => a.order - b.order);
  ctx.addArtifact("release_plan", { releases: releases, pipeline: pipeline });
  return releases.length + " release(s), " + pipeline.length + " environment(s)";
}

