Intent: "{{ .Change.Intent }}"
Change impacts:
{{ range .ChangeImpacts }}- {{ .Intent }} {{ .Type }} {{ .Key }}: {{ .Rationale }}
{{ end }}
Artifacts:
{{ range .Artifacts }}- {{ .Target }} {{ json .Data }}
{{ end }}
Write the release note (requirements, components, artifacts, releases,
affected applications, tests, deployment chain):
{"type":"artifact","target":"release_note","data":{"markdown":"..."}}

actions.code:
function run(ctx) {
  const lines = ["# Release Note", "", "Intent: " + ctx.intent(), ""];
  const section = (title, rows) => { if (rows.length) { lines.push("## " + title, ...rows.map(r => "- " + r), ""); } };
  const nodes = ctx.changeImpacts().filter(n => n.post || n.intent === "created");
  const verb = n => (n.intent === "created" ? "create " : "update ");
  section("Requirements", nodes.filter(n => n.type.endsWith("Requirement")).map(n => verb(n) + n.key));
  section("Design", nodes.filter(n => ["alm@Function", "alm@Component", "alm@Interface", "alm@Flow", "alm@Data"].includes(n.type)).map(n => verb(n) + n.type + " " + n.key));
  section("Build artifacts", ctx.items("artifact").filter(a => a.target === "build").map(a => a.data.artifact + " (" + a.data.toolchain + ")"));
  section("Tests", nodes.filter(n => n.type === "alm@TestCase").map(n => n.key));
  section("Releases", nodes.filter(n => n.type === "alm@Release").map(n => n.key + " " + ((n.post && n.post.props.title) || "")));
  const plan = ctx.items("artifact").filter(a => a.target === "release_plan").pop();
  if (plan) section("Deployment", [plan.data.pipeline.map(e => e.name + " (" + e.stage + ")").join(" → ")]);
  section("Affected applications", ctx.changeImpacts().filter(n => n.intent === "modified" && n.type === "alm@Application" && n.pre).map(n => n.key + " " + (n.pre.props.title || "")));
  ctx.addArtifact("release_note", { markdown: lines.join("\n") });
  return "release note assembled";
}

function run(ctx) {
  const types = ["alm@Requirement", "alm@FunctionalRequirement", "alm@NonFunctionalRequirement", "alm@SecurityRequirement"];
  let approved = 0;
  for (const n of ctx.changeImpacts()) {
    if (!types.includes(n.type) || n.review !== "accepted" || !n.post) continue;
    const state = n.post.state;
    if (state === "proposed") ctx.impactNodeTransition(n.key, "draft");
    if (state === "proposed" || state === "draft") {
      ctx.impactNodeTransition(n.key, "approved");
      approved++;
    }
  }
  let candidates = 0;
  for (const n of ctx.changeImpacts()) {
    if (n.type !== "alm@Release" || n.review !== "accepted" || !n.post || n.post.state !== "draft") continue;
    ctx.impactNodeTransition(n.key, "candidate");
    candidates++;
  }
  ctx.addArtifact("requirements_approval", { approved: approved, candidates: candidates });
  return approved + " requirement(s) approved";
}

function run(ctx) {
  const plan = ctx.items("artifact").filter(a => a.target === "release_plan").pop();
  const waves = ctx.items("artifact").filter(a => a.target === "deployment_wave");
  const env = plan.data.pipeline[waves.length];
  if (!env) throw new Error("all waves are deployed");
  const checks = ctx.param("checks") || [];
  const tests = ctx.changeImpacts().filter(n => n.intent === "created" && n.type === "alm@TestCase" && n.post);
  const campaign = {};
  for (const t of tests) campaign[t.post.props.level || "acceptance"] = (campaign[t.post.props.level || "acceptance"] || 0) + 1;
  for (const r of plan.data.releases) {
    const d = ctx.impactNodeCreate("alm@Deployment", "DEP-" + r + "-" + env.key, "deployment of " + r + " to " + env.name);
    ctx.writeNode(d, { props: { status: "succeeded", stage: env.stage, checks: checks },
      links: [{ type: "alm@of_release", to: r }, { type: "alm@in_environment", to: env.key }] });
    // a deployment is recorded once done: no review to wait for
    ctx.impactNodeReview(d, true, "deployment recorded");
  }
  ctx.addArtifact("deployment_wave", { environment: env.key, name: env.name, stage: env.stage, releases: plan.data.releases,
    checks: checks, tests: campaign });
  return plan.data.releases.length + " release(s) deployed to " + env.name;
}

