function lines(s) { return String(s || "").split("\n").map(x => x.trim()).filter(x => x); }
function run(ctx) {
  const a = ctx.var("item");
  const f = ctx.var("form") || {};
  const titles = {};
  for (const r of ctx.items("risk")) if (r.data.title) titles[r.data.key] = r.data.title;
  // the hypotheses are its requirements: a risk it checks holds, or a statement about the need
  const hypotheses = [];
  for (const k of (a.risks || [])) hypotheses.push({ statement: k + " holds: " + (titles[k] || k), source: k });
  for (const st of (a.hypotheses || []).concat(lines(f.hypotheses))) hypotheses.push({ statement: st, source: "framing" });
  if (hypotheses.length === 0) throw new Error("the proof of concept checks nothing: name a risk on the action, or a statement");
  const me = ctx.callTool("goap-change/read", {}).change;
  const what = a.purpose === "explore" ? "Prototype" : "POC";
  const intent = what + " for " + me.title + ": " + hypotheses.map(h => h.statement).join("; ") +
    (f.timebox ? " (timebox " + f.timebox + ")" : "");
  const sub = ctx.callTool("goap-change/create", { parent: me.id, title: what + ": " + a.title, intent: intent,
    methodology: "poc", criticality: "C1", data: { poc: { action: a.key, purpose: a.purpose, parent: me.id } } }).change;
  // what it checks, for the sub-change to state as its own hypotheses
  ctx.callTool("goap-change/note", { change: sub.id, target: "poc_scope", text: intent, data: { action: a.key,
    purpose: a.purpose, parent: me.id, hypotheses: hypotheses, repositories: lines(f.repositories),
    timebox: f.timebox || "", notes: f.notes || "" } });
  ctx.addItem("action", { key: a.key, title: a.title, change: sub.id });
  return what + " opened: " + sub.id;
}

function run(ctx) {
  const a = ctx.var("item");
  const sub = ctx.callTool("goap-change/read", { change: a.change });
  const items = sub.items || [];
  const last = (type, key) => items.filter(i => i.type === type && i.data && i.data.key === key).pop();
  const conclusion = items.filter(i => i.type === "artifact" && i.target === "poc_conclusion").pop();
  const kept = items.filter(i => i.type === "artifact" && i.target === "probes_kept").pop();
  const titles = {};
  for (const r of ctx.items("risk")) if (r.data.title) titles[r.data.key] = r.data.title;
  const verdicts = [];
  for (const h of items.filter(i => i.type === "hypothesis")) {
    const v = last("assessment", "item:" + h.data.key);
    const verdict = v ? v.data.verdict : "confirmed"; // no verdict: it was not shown to work
    const findings = v && v.data.findings ? v.data.findings : [];
    verdicts.push({ hypothesis: h.data.key, statement: h.data.statement, source: h.data.source, verdict: verdict,
      findings: findings, suggestion: v ? v.data.suggestion || "" : "" });
    const risk = h.data.source;
    if (!titles[risk]) continue;
    // the verdict on the risk, where the register reads it (ADR 0110 §6, the bubble of the risk)
    ctx.addItem("assessment", { key: "item:" + risk, verdict: verdict, score: v ? v.data.score : 0, findings: findings,
      from: a.change });
    if (verdict === "refuted") {
      ctx.addItem("risk", { key: risk, title: titles[risk], status: "closed",
        rationale: "the proof of concept " + a.key + " showed it works as expected (" + a.change + ")" });
    } else {
      // it holds: the concluded POC no longer covers it, the risk management asks for another mitigation
      ctx.addItem("risk", { key: risk, title: titles[risk], status: "open",
        rationale: "the proof of concept " + a.key + " confirmed it (" + a.change + "): another mitigation is needed" });
    }
  }
  const findings = { action: a.key, purpose: a.purpose, change: a.change, verdicts: verdicts,
    summary: conclusion ? conclusion.data.summary || "" : "", branches: kept ? kept.data.branches || [] : [] };
  // for the delivery: what the POC learnt and where its code is, a reference, never reused as is (ADR 0131 §5)
  ctx.addArtifact("poc_findings", findings);
  if (a.purpose === "explore") {
    // for the person confirming the framing: never applied to the description by itself (ADR 0110 §4)
    ctx.addArtifact("prototype_findings", findings);
  }
  const result = verdicts.map(v => v.hypothesis + " " + v.verdict + ": " + v.statement).join("; ");
  ctx.addItem("action", { key: a.key, title: a.title, status: "done", result: result });
  ctx.callTool("goap-change/close", { change: a.change, reason: "proof of concept concluded, nothing to commit" });
  return a.key + " concluded: " + result;
}
